<template><view class="page"><view class="nav"><text @click="back">返回</text><text class="nav-title">我的体验</text><text /></view><LoadingState v-if="loading" title="正在加载体验记录" description="正在同步你的申请和反馈。" /><EmptyState v-else-if="error" variant="error" title="我的体验加载失败" :description="error" action-text="重新加载" @action="load" /><EmptyState v-else-if="!rows.length" variant="social" title="还没有体验申请" description="去开放项目中申请一次真实体验吧。" action-text="去看看开放项目" @action="openProjects" /><view v-else class="list"><view v-for="item in rows" :key="item.id" class="card"><view class="card-head"><text class="title">{{ item.project.title }}</text><text class="badge" :class="item.status">{{ statusText(item.status) }}</text></view><text class="copy">{{ item.project.description || '真实参与，真实反馈。' }}</text><button v-if="item.status === 'approved' && feedbackId !== item.id" class="primary" @click="feedbackId=item.id">提交体验反馈</button><view v-if="feedbackId === item.id" class="feedback-form"><textarea v-model="feedbackText" maxlength="1000" class="feedback-input" placeholder="请填写真实体验，至少 10 个字" auto-height /><view class="feedback-foot"><text>{{ feedbackText.length }}/1000</text><button class="secondary" @click="feedbackId=0">取消</button><button class="primary small" :disabled="sending || feedbackText.trim().length < 10" @click="submitFeedback(item)">{{ sending ? '提交中…' : '提交反馈' }}</button></view></view><text v-else-if="item.status === 'feedback_submitted'" class="hint">反馈已提交，等待审核</text><text v-else-if="item.status !== 'approved'" class="hint">审核通过后可提交反馈</text></view></view><view class="bottom-space" /></view></template>
<script setup lang="ts">import {onShow} from '@dcloudio/uni-app';import {ref} from 'vue';import EmptyState from '../../components/EmptyState.vue';import LoadingState from '../../components/LoadingState.vue';import {ensureUser,request,withTenantCode} from '../../api';const rows=ref<any[]>([]),loading=ref(true),error=ref(''),feedbackId=ref(0),feedbackText=ref(''),sending=ref(false);const statusText=(v:string)=>({pending:'审核中',approved:'已通过',rejected:'未通过',feedback_submitted:'已反馈'} as any)[v]||v;async function load(){loading.value=true;error.value='';try{await ensureUser();rows.value=await request<any[]>('/public/experiences/my')}catch(e:any){error.value=e?.message||'我的体验加载失败'}finally{loading.value=false}}async function submitFeedback(item:any){if(sending.value||feedbackText.value.trim().length<10)return;sending.value=true;try{await request(`/public/experiences/applications/${item.id}/feedback`,{method:'POST',data:{rating:5,content:feedbackText.value.trim()}});uni.showToast({title:'反馈已提交',icon:'none'});feedbackId.value=0;feedbackText.value='';await load()}catch(e:any){uni.showToast({title:e?.message||'提交失败',icon:'none'})}finally{sending.value=false}}function openProjects(){uni.navigateTo({url:withTenantCode('/pages/experience/index')})}function back(){uni.navigateBack()}onShow(load)</script>
<style scoped>.page{min-height:100vh;background:#f5f7f5;color:#18251e;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif}.nav{height:92rpx;padding:0 28rpx;display:grid;grid-template-columns:100rpx 1fr 100rpx;align-items:center;background:#fff;color:#08753f;font-size:25rpx}.nav-title{text-align:center;color:#18251e;font-size:30rpx;font-weight:900}.state{display:grid;gap:12rpx;margin:28rpx;padding:36rpx;border-radius:16rpx;background:#fff;color:#748079;text-align:center;font-size:24rpx}.error{color:#b42318}.empty-title{color:#24342b;font-size:28rpx;font-weight:900}.link-button{border:0;background:transparent;color:#08753f}.list{display:grid;gap:16rpx;padding:28rpx}.card{padding:26rpx;border:1rpx solid #e0e8e3;border-radius:16rpx;background:#fff}.card-head{display:flex;justify-content:space-between;gap:16rpx}.title{font-size:29rpx;font-weight:900}.badge{padding:7rpx 12rpx;border-radius:8rpx;background:#fff4d8;color:#996100;font-size:21rpx}.badge.approved{background:#e8f7ed;color:#08753f}.badge.rejected{background:#fff0ef;color:#b42318}.copy{display:block;margin-top:16rpx;color:#536159;font-size:24rpx;line-height:1.6}.primary{width:100%;height:68rpx;margin-top:20rpx;border:0;border-radius:12rpx;background:#08753f;color:#fff;font-size:25rpx}.primary::after{border:0}.primary[disabled]{opacity:.55}.feedback-form{margin-top:18rpx;padding-top:18rpx;border-top:1rpx solid #e5ebe7}.feedback-input{width:100%;min-height:180rpx;padding:18rpx;box-sizing:border-box;border:1rpx solid #dbe5df;border-radius:10rpx;background:#fbfdfb;font-size:24rpx;line-height:1.6}.feedback-foot{display:flex;align-items:center;gap:10rpx;margin-top:12rpx;color:#748079;font-size:21rpx}.feedback-foot text{margin-right:auto}.secondary{height:58rpx;margin:0;padding:0 16rpx;border:1rpx solid #d4dfd8;border-radius:10rpx;background:#fff;color:#506159;font-size:22rpx;line-height:58rpx}.secondary::after{border:0}.primary.small{width:auto;height:58rpx;margin:0;padding:0 18rpx;font-size:22rpx;line-height:58rpx}.hint{display:block;margin-top:18rpx;color:#748079;font-size:23rpx}.bottom-space{height:40rpx}</style>
